def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    horizontal_rails = [
        r for r in range(h) if sum(x == 2 for x in grid[r]) >= w - 3
    ]
    vertical_rails = [
        c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h - 3
    ]

    rays = []
    for r, c in centers:
        if r in horizontal_rails:
            rays.append(("v", r, c))
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
        elif c in vertical_rails:
            rays.append(("h", r, c))
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1

    # Where a ray crosses a perpendicular 2-rail, mark a 3x3 flare.
    for direction, r, c in rays:
        crossings = vertical_rails if direction == "h" else horizontal_rails
        for k in crossings:
            cr, cc = (r, k) if direction == "h" else (k, c)
            for rr in range(max(0, cr - 1), min(h, cr + 2)):
                for x in range(max(0, cc - 1), min(w, cc + 2)):
                    if (rr, x) == (cr, cc):
                        continue
                    if out[rr][x] in (0, 2):
                        out[rr][x] = 1

    return out
